package br.com.admeclesial.interfaces.rest.financeiro; import br.com.admeclesial.application.financeiro.*; import br.com.admeclesial.domain.financeiro.CategoriaFinanceira; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/categorias-financeiras") public class CategoriaFinanceiraRestController { final CategoriaFinanceiraApplicationService s; public CategoriaFinanceiraRestController(CategoriaFinanceiraApplicationService s){this.s=s;} @PostMapping public CategoriaFinanceira criar(@Valid @RequestBody CategoriaFinanceiraRequest r){return s.criar(r);} @GetMapping public List<CategoriaFinanceira> listar(){return s.listar();} }